select 'transition_snapshot'::text as source,model_version,count(*) as rows,min(captured_at)::text as earliest,max(captured_at)::text as latest from private.jra_model_transition_snapshots group by model_version union all select 'rank_snapshot',model_version,count(*),min(created_at)::text,max(created_at)::text from public.jra_live_rank_snapshots group by model_version union all select 'worker_runs',worker_id||':'||status,count(*),min(started_at)::text,max(started_at)::text from public.jra_prediction_worker_runs where started_at>='2026-10-17' and started_at<'2026-11-16' group by worker_id,status order by source,model_version limit 30;
